import{_ as n,b as a,c as t,g as p}from"./chunks/framework.86O3EbG5.js";const h=JSON.parse('{"title":"电影摄影：理论与实践","description":"","frontmatter":{"title":"电影摄影：理论与实践","subTitle":"电影作为一种语言","author":"oasis","date":"2026-09-21T00:00:00.000Z","tags":["读书笔记"]},"headers":[],"relativePath":"articles/books/cinematography-theory-and-practice/1.md","filePath":"articles/books/cinematography-theory-and-practice/1.md"}'),l={name:"articles/books/cinematography-theory-and-practice/1.md"};function i(e,s,o,r,g,c){return a(),t("div",null,[...s[0]||(s[0]=[p(`<p>电影是一种语言：包括镜头、构图、视觉设计、灯光、图像控制、连续性、动作和视角。</p><h2 id="电影中的领域语言" tabindex="-1">电影中的领域语言</h2><ul><li><strong>画面</strong>：电影的基础，引导观众的注意力。画面的选择关乎影片结构、故事节奏和内涵观点。</li><li><strong>光线和色彩</strong>：和摄像中的光线具有同样重要的地位，光线和色彩在表达氛围、感情上非常重要。</li><li><strong>镜头</strong>：不同种类镜头产生不同的效果，如何产生不同的效果，这是讨论的重点。</li><li><strong>运动</strong>：电影是集合运动和时间的艺术形式。</li><li><strong>质感</strong>：对真实场景的加工，实际上可以和摄像中的主题概念关联，不过在电影中，应该是一种情感或主观上的感受。</li><li><strong>定场</strong>：摄影机传达或隐藏信息的能力，是视觉形式的阐述。目的是向观众传达重要信息或故事背景。</li><li><strong>视角（POV）</strong>：摄影机本质上是观众的视觉工具，不同的视角会产生不同的情感或理解。</li></ul><h2 id="摄影技法" tabindex="-1">摄影技法</h2><p>本书对电影的定义：控制观众从每个场景中获得的信息，不仅仅是理性上的（电影情节），也可以是感性上的。</p><p>电影实际上是引导观众自己提出「下一幕是什么」这样的问题。</p><p>电影是对现实的解构和重构。先拍摄场景中不同的镜头，再通过主观进行重构。</p><h3 id="镜头分类" tabindex="-1">镜头分类</h3><ul><li><strong>远景</strong>：包括整个场景。</li><li><strong>定场镜头</strong>：通常是一个远景，用于开场、传达给观众信息，为后续不同镜头之间建立关系。</li><li><strong>全景镜头</strong>：从头到脚看到人。</li><li><strong>七分身镜头</strong></li><li><strong>双人镜头</strong></li><li><strong>反应镜头</strong><ul><li><strong>中景</strong></li><li><strong>特写</strong><ul><li><strong>中特写</strong>：胸口以上</li><li><strong>面部特写</strong>：喉咙以上</li><li><strong>大头特写</strong>：下巴以上，并且会切掉部分头发或头部</li><li><strong>大特写</strong>：通常只拍嘴巴和眼睛</li></ul></li></ul></li><li><strong>纯单人镜头</strong></li><li><strong>不纯单人镜头</strong></li><li><strong>大特写</strong></li><li><strong>过肩镜头（OTS）</strong>：越过一位演员的肩膀，拍摄另一个演员或场景的中景或特写，它能够将两个人物联系起来。</li><li><strong>旁跳镜头</strong>：拍场景中的某个人或事的镜头，仍然和场景相关。在主镜头或全景中没看到的东西。</li><li><strong>插入镜头</strong>：更大的场景中独立的、自成一派的镜头。主体一定是我们在全景中看到过的东西。</li><li><strong>连续镜头</strong></li><li><strong>补拍镜头</strong></li><li><strong>转场镜头</strong></li></ul><h3 id="摄影方法" tabindex="-1">摄影方法</h3><ul><li><strong>主场景法</strong>：先把整个场景完整拍一遍，再补各种局部镜头。</li><li><strong>备选镜头</strong>：为剪辑准备的各种「零件」。</li><li><strong>重叠法 / 三拍法</strong>：走进房间 → 放下文件 → 拉椅子 → 坐下。</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span>镜头 A：[走进----放文件]</span></span>
<span class="line"><span>镜头 B：[走进----放文件----拉椅子]</span></span>
<span class="line"><span>镜头 C：[拉椅子----坐下]</span></span></code></pre></div><ul><li><strong>单镜头</strong>：整场戏只用一个连续镜头完成。</li><li><strong>自由变形法</strong>：不严格遵循某一种固定拍摄套路，根据场景自由组合。这个场景需要什么，我就怎么拍。</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span>主场景</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>跟拍</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>突然特写</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>反打</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>手持</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>再回到全景</span></span></code></pre></div><ul><li><strong>蒙太奇</strong>：把不同镜头放在一起，让观众自己产生新的意义。镜头 A：一个人抬头；镜头 B：一座高楼。观众理解：人在看高楼。</li></ul><h2 id="观众的代入感" tabindex="-1">观众的代入感</h2><h3 id="第四面墙和视角" tabindex="-1">第四面墙和视角</h3><p>想象一个房间：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span>        墙</span></span>
<span class="line"><span>┌─────────────┐</span></span>
<span class="line"><span>│             │</span></span>
<span class="line"><span>│    演员     │</span></span>
<span class="line"><span>│             │</span></span>
<span class="line"><span>│             │</span></span>
<span class="line"><span>└─────────────┘</span></span>
<span class="line"><span>      ↑</span></span>
<span class="line"><span>    摄影机</span></span></code></pre></div><p>传统戏剧中：后、左、右三面墙 + 一面「看不见的墙」。</p><p>摄影机 / 观众就在第四面墙外。演员通常不看观众。这就形成一种：「我在偷偷观察这个世界。」</p><p>什么时候打破第四面墙？如果演员突然看向镜头。</p><p>观众原本：「我正在观察这个人物。」突然变成：「这个人物知道我在看他。」关系发生了变化。</p><p>例如：</p><p>普通：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span>人物 → 对着另一个人物说话</span></span>
<span class="line"><span> ↑</span></span>
<span class="line"><span>摄影机</span></span></code></pre></div><p>打破第四墙：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span>人物 ─────────→ 摄影机</span></span>
<span class="line"><span>                ↑</span></span>
<span class="line"><span>              观众</span></span></code></pre></div><p>此时演员实际上是在直接对观众说话。这会强烈改变观众的位置感。</p>`,29)])])}const u=n(l,[["render",i]]);export{h as __pageData,u as default};
